import re


UNEMP_RE = re.compile(r"un\s*em\s*ploy\s*ment\s*rate|civilian\s*unemployment\s*rate", re.IGNORECASE)
PERCENT_RE = re.compile(r"\b\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\b", re.IGNORECASE)
MONTH_RE = re.compile(
    r"\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\b",
    re.IGNORECASE,
)
MONTH_YEAR_RE = re.compile(
    r"\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{4}\b",
    re.IGNORECASE,
)
DATE_MARKERS_RE = re.compile(
    r"\b(?:recent|latest|current|now|as of|in|during|since|stood at|fell to|rose to|edged down to|dropped to|declined to|hovered|reached|hit|was|were)\b",
    re.IGNORECASE,
)
RATE_WORDS_RE = re.compile(r"\b(?:percent|per\s*cent)\b", re.IGNORECASE)


def _normalize(text: str) -> str:
    text = text or ""
    text = re.sub(r"(\w)-\s+(\w)", r"\1\2", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def _compact(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", _normalize(text).lower())


def _score_text(text: str) -> int:
    low = text.lower()
    compact = _compact(text)
    score = 0
    if "unemploymentrate" in compact or "civilianunemploymentrate" in compact:
        score += 6
    if PERCENT_RE.search(low):
        score += 4
    if MONTH_YEAR_RE.search(low):
        score += 3
    elif MONTH_RE.search(low):
        score += 2
    if DATE_MARKERS_RE.search(low):
        score += 2
    if any(tok in compact for tok in ("edgeddown", "fellt", "roset", "stoodat", "hovered", "droppedto", "declinedto", "reached", "hit", "stable")):
        score += 1
    return score


def _sentence_spans(text: str) -> list[str]:
    text = _normalize(text)
    if not text:
        return []
    chunks = re.split(r"(?<=[.!?])\s+", text)
    if len(chunks) == 1:
        return [text]
    return [chunk.strip() for chunk in chunks if chunk.strip()]


def _extract_rate_phrase(text: str) -> str | None:
    text = _normalize(text)
    if not text:
        return None
    patterns = [
        r"(?:stood at|stood|was|were)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"(?:edged down to|fell to|dropped to|declined to|rose to|increased to|has risen to|has fallen to|has crept lower to)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"(?:reached|peaked at|hit)\s+(?:a\s+[^,.;:]+?\s+)?(?:of\s+)?(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"(?:from|between)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
        r"range of\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+(?P<rate>\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent))",
    ]
    for pattern in patterns:
        m = re.search(pattern, text, re.IGNORECASE)
        if m:
            rate = _normalize(m.group("rate"))
            if rate:
                return rate
    matches = list(PERCENT_RE.finditer(text))
    if not matches:
        return None
    # Prefer the last percentage when the sentence describes a range or a before/after comparison.
    return _normalize(matches[-1].group(0))


def _extract_context_phrase(text: str) -> str | None:
    text = _normalize(text)
    if not text:
        return None
    patterns = [
        r"rose from\s+.*?\s+to\s+.*?\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)(?:\s+(?:in|as of)\s+[A-Za-z]+\s+\d{4})?",
        r"(?:stood at|stood|was|were)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"(?:edged down to|fell to|dropped to|declined to|rose to|increased to|has risen to|has fallen to|has crept lower to)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"(?:reached|peaked at|hit)\s+(?:a\s+[^,.;:]+?\s+)?(?:of\s+)?\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)(?:\s+(?:in|as of)\s+[A-Za-z]+\s+\d{4})?",
        r"(?:from|between)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"range of\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
        r"hovered in a narrow range of\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)\s+(?:to|and)\s+\d{1,2}(?:\.\d+)?\s*(?:per\s*cent|percent)",
    ]
    for pattern in patterns:
        m = re.search(pattern, text, re.IGNORECASE)
        if m:
            return _normalize(m.group(0))
    return None


def rule_unemployment_rate_recent(doc: dict) -> list[dict]:
    try:
        best_span = None
        best_score = 0
        seen = set()

        paragraphs = doc.get("paragraphs") or []
        for para in paragraphs:
            text = para.get("text") or ""
            if not text:
                continue
            compact = _compact(text)
            if "unemploymentrate" not in compact and "civilianunemploymentrate" not in compact:
                continue
            sentences = _sentence_spans(text)
            best = None
            best_score = 0
            for sent in sentences:
                score = _score_text(sent)
                if score > best_score:
                    best = sent
                    best_score = score
            if best is None:
                best = _normalize(text)
                best_score = _score_text(best)
            if best_score < 8:
                continue
            phrase = _extract_rate_phrase(best)
            context = _extract_context_phrase(best)
            if phrase and context and phrase != context:
                best_context = context
                best = phrase
            else:
                best_context = context
                if phrase:
                    best = phrase
            key = (para.get("page_no"), para.get("paragraph_no"), best)
            if key in seen:
                continue
            seen.add(key)
            if best_score > 0 and (best_span is None or best_score > best_span[0]):
                spans_to_return = []
                if best_context and best_context != best:
                    span2 = {"text": best_context}
                    if para.get("page_no") is not None:
                        span2["page_no"] = para["page_no"]
                    if para.get("paragraph_no") is not None:
                        span2["paragraph_no"] = para["paragraph_no"]
                    spans_to_return.append(span2)
                span = {"text": best}
                spans_to_return.append(span)
                best_span = (best_score, spans_to_return)

        lines = doc.get("lines") or []
        for idx, line in enumerate(lines):
            text = line.get("text") or ""
            if not text:
                continue
            compact = _compact(text)
            if "unemploymentrate" not in compact and "civilianunemploymentrate" not in compact:
                continue
            window_parts = []
            for j in range(max(0, idx - 2), min(len(lines), idx + 4)):
                part = _normalize(lines[j].get("text") or "")
                if part:
                    window_parts.append(part)
            window = " ".join(window_parts).strip()
            if not window:
                continue
            score = _score_text(window)
            if score < 8:
                continue
            phrase = _extract_rate_phrase(window)
            context = _extract_context_phrase(window)
            if phrase:
                window = phrase
            key = (line.get("page_no"), line.get("line_no"), window)
            if key in seen:
                continue
            seen.add(key)
            if best_span is None or score > best_span[0]:
                spans_to_return = []
                if context and context != window:
                    span2 = {"text": context}
                    if line.get("page_no") is not None:
                        span2["page_no"] = line["page_no"]
                    if line.get("line_no") is not None:
                        span2["line_no"] = line["line_no"]
                    spans_to_return.append(span2)
                span = {"text": window}
                spans_to_return.append(span)
                best_span = (score, spans_to_return)

        if best_span is None:
            return []
        return best_span[1]
    except Exception:
        return []

import re


def rule_fd_public_debt_latest_fy(doc: dict) -> list[dict]:
    try:
        line_objs = doc.get("lines") or []
        if line_objs and isinstance(line_objs[0], dict):
            lines = [str(x.get("text", "")) for x in line_objs]
        else:
            lines = str(doc.get("text", "")).splitlines()
            line_objs = [{"text": t} for t in lines]

        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", str(text or "")).strip()

        month_pat = re.compile(
            r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec|"
            r"january|february|march|april|june|july|august|september|"
            r"october|november|december)\b",
            re.I,
        )
        year_pat = re.compile(r"^\s*(19|20)\d{2}\b")

        def find_start(phrases: tuple[str, ...]) -> int | None:
            for i in range(len(lines)):
                window = " ".join(norm(lines[j]) for j in range(i, min(len(lines), i + 3))).lower()
                if "table fd" not in window:
                    continue
                if not any(p in window for p in phrases):
                    continue
                if any(
                    year_pat.match(norm(lines[j])) for j in range(i + 1, min(len(lines), i + 120))
                ):
                    return i
            for i in range(len(lines) - 1):
                window = (norm(lines[i]) + " " + norm(lines[i + 1])).lower()
                if "table fd" not in window:
                    continue
                if not any(p in window for p in phrases):
                    continue
                if any(
                    year_pat.match(norm(lines[j])) for j in range(i + 1, min(len(lines), i + 120))
                ):
                    return i
            return None

        def extract_latest_row(start: int) -> dict | None:
            search_end = min(len(lines), start + 260)
            year_rows: list[int] = []
            saw_year_block = False
            for i in range(start, search_end):
                t = norm(lines[i])
                if not t:
                    continue
                if year_pat.match(t) and not month_pat.search(t):
                    year_rows.append(i)
                    saw_year_block = True
                    continue
                if saw_year_block:
                    if month_pat.search(t):
                        break
                    if t.lower().startswith("table fd"):
                        break
            if not year_rows:
                return None
            row_start = year_rows[-1]
            row_end = min(search_end, row_start + 30)
            for i in range(row_start + 1, row_end):
                if norm(lines[i]).lower().startswith("table fd"):
                    row_end = i
                    break

            span_text = "\n".join(lines[start:row_end]).strip()
            if not span_text:
                return None

            span = {"text": span_text}
            if line_objs and isinstance(line_objs[row_start], dict):
                span["page_no"] = line_objs[row_start].get("page_no")
                span["line_no"] = line_objs[row_start].get("line_no")
                span["end_page_no"] = line_objs[row_end - 1].get("page_no")
                span["end_line_no"] = line_objs[row_end - 1].get("line_no")
            return span

        spans: list[dict] = []

        # First try the modern summary table, then fall back to the older public-debt table.
        for phrases in (
            ("summary of federal debt",),
            ("debt held by the public", "interest-bearing public debt"),
        ):
            start = find_start(phrases)
            if start is None:
                continue
            span = extract_latest_row(start)
            if span is not None:
                spans.append(span)

        return spans
    except Exception:
        return []

import re


def rule_michigan_consumer_sentiment_latest_reading(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return " ".join((text or "").split())

        trigger_pat = re.compile(
            r"(?i)\b(?:reuters/?michigan|university of michigan|michigan index of consumer sentiment|"
            r"consumer sentiment survey|consumer sentiment index|index of consumer sentiment|"
            r"sentiment index)\b"
        )
        exclude_pat = re.compile(r"(?i)\b(?:conference board|consumer confidence)\b")

        reading_pats = [
            re.compile(
                r"(?i)\b(?:has\s+|had\s+)?(?:declined(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"fallen(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"fell(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"rose(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+to|"
                r"stood at|standing at|"
                r"moving(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+up\s+to|"
                r"moved(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+up\s+to|"
                r"moved(?:\s+(?:\d+(?:\.\d+)?|[A-Za-z]+)){0,4}?\s+higher,\s+reaching|"
                r"trended higher,\s+reaching|reaching)\s+"
                r"(?:just|only|about|roughly|around|approximately|nearly|close to|slightly|modestly|marginally|"
                r"somewhat|a bit|a record low of|a record high of|a multi-year low of|a multi-year high of|"
                r"a 14-year high of|a 18-year high of)?\s*"
                r"\d+(?:\.\d+)?(?:\s+(?:in|during|by|at|as of|for)\s+[^.;,\n]{1,40})?"
            ),
            re.compile(
                r"(?i)\b(?:reached)\s+(?:a\s+)?(?:record low|record high|multi-year low|multi-year high|"
                r"14-year high|18-year high)\s+of\s+\d+(?:\.\d+)?"
            ),
        ]

        def best_phrase(block: str) -> str:
            block = norm(block)
            if not block:
                return ""
            best = ""
            best_pos = -1
            for pat in reading_pats:
                for m in pat.finditer(block):
                    if m.start() >= best_pos:
                        best_pos = m.start()
                        best = norm(m.group(0).rstrip(" ,;:"))
            return best

        def scan_text(text: str) -> list[str]:
            text = norm(text)
            if not text or not trigger_pat.search(text):
                return []

            block = text
            exclude_match = exclude_pat.search(block)
            if exclude_match:
                block = block[: exclude_match.start()]

            out: list[str] = []
            for pat in reading_pats:
                for m in pat.finditer(block):
                    phrase = norm(m.group(0).rstrip(" ,;:"))
                    if phrase:
                        out.append(phrase)
            return out

        def scan_windows(items: list[dict], key: str, meta_key: str, window_size: int = 12) -> list[dict]:
            ordered = [item for item in items if item.get(key)]
            best_hit: dict | None = None
            best_idx = 10**9
            for idx in range(len(ordered)):
                window = ordered[idx : idx + window_size]
                lead_block = norm(" ".join((item.get(key) or "") for item in window[:2]))
                if not lead_block or not trigger_pat.search(lead_block):
                    continue
                block = norm(" ".join((item.get(key) or "") for item in window))

                exclude_match = exclude_pat.search(block)
                if exclude_match:
                    block = block[: exclude_match.start()]

                phrase = best_phrase(block)
                if phrase:
                    if idx < best_idx:
                        best_idx = idx
                        first = window[0]
                        span = {"text": phrase}
                        if first.get("page_no") is not None:
                            span["page_no"] = first.get("page_no")
                        if first.get(meta_key) is not None:
                            span[meta_key] = first.get(meta_key)
                        best_hit = span
            return [best_hit] if best_hit else []

        ordered_paragraphs = sorted(
            [item for item in (doc.get("paragraphs") or []) if item.get("text")],
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("paragraph_no", 10**9),
            ),
        )
        ordered_lines = sorted(
            [item for item in (doc.get("lines") or []) if item.get("text")],
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("line_no", 10**9),
            ),
        )
        hits = scan_windows(ordered_lines, "text", "line_no", window_size=12)
        if hits:
            return hits

        for item in ordered_paragraphs:
            phrases = scan_text(item.get("text") or "")
            if phrases:
                return [
                    {
                        "text": phrases[-1],
                        "page_no": item.get("page_no"),
                        "paragraph_no": item.get("paragraph_no"),
                    }
                ]

        return []
    except Exception:
        return []

import re


DATE_RE = re.compile(
    r"^\s*(?:"
    r"Jan(?:uary)?\.?|Feb(?:ruary)?\.?|Mar(?:ch)?\.?|Apr(?:il)?\.?|"
    r"May|Jun(?:e)?\.?|Jul(?:y)?\.?|Aug(?:ust)?\.?|"
    r"Sep(?:t(?:ember)?)?\.?|Sept\.?|Oct(?:ober)?\.?|"
    r"Nov(?:ember)?\.?|Dec(?:ember)?\.?"
    r")\s+\d{1,2},\s+\d{4}\s*$",
    re.IGNORECASE,
)


def _norm(text: str) -> str:
    return re.sub(r"\s+", " ", str(text or "")).strip()


def _window_text(lines: list[str], start: int, end: int) -> str:
    parts = []
    for idx in range(max(0, start), min(len(lines), end)):
        txt = _norm(lines[idx])
        if txt:
            parts.append(txt)
    return " ".join(parts)


def _has_per_capita(lines: list[str], start: int) -> bool:
    return "per capita" in _window_text(lines, start, start + 3).lower()


def _find_date_idx(lines: list[str], start: int, stop: int) -> int | None:
    for idx in range(start, min(len(lines), stop)):
        if DATE_RE.match(_norm(lines[idx])):
            return idx
    return None


def _collect_nonempty_lines(lines: list[str], start: int, count: int) -> int:
    seen = 0
    idx = start
    while idx < len(lines) and seen < count:
        if _norm(lines[idx]):
            seen += 1
        idx += 1
    return idx


def rule_uscc2_latest_per_capita(doc: dict) -> list[dict]:
    try:
        line_objs = doc.get("lines") or []
        if line_objs and isinstance(line_objs[0], dict):
            lines = [str(item.get("text", "")) for item in line_objs]
        else:
            lines = str(doc.get("text", "")).splitlines()
            line_objs = [{"text": text} for text in lines]

        markers = (
            "comparative totals of currency and coins in circulation",
            "currency in circulation by denomination",
            "amounts outstanding and in circulation",
            "table uscc-2",
            "uscc-2",
        )

        best = None

        for idx in range(len(lines)):
            window = _window_text(lines, idx, idx + 4).lower()
            if not window:
                continue

            if "per capita" not in window:
                continue

            context = _window_text(lines, max(0, idx - 8), idx + 1).lower()
            if not any(marker in context for marker in markers):
                continue

            date_idx = _find_date_idx(lines, idx + 1, idx + 16)
            if date_idx is None:
                continue

            header_idx = None
            for back in range(idx, max(-1, idx - 12), -1):
                back_text = _norm(lines[back]).lower()
                if "comparative totals of currency and coins in circulation" in back_text:
                    header_idx = back
                    break
            if header_idx is None:
                for back in range(idx, max(-1, idx - 12), -1):
                    back_text = _norm(lines[back]).lower()
                    if (
                        "currency in circulation by denomination" in back_text
                        or "table uscc-2" in back_text
                        or "amounts outstanding and in circulation" in back_text
                    ):
                        header_idx = back
                        break
            if header_idx is None:
                header_idx = max(0, idx - 4)

            end_idx = _collect_nonempty_lines(lines, date_idx, 3)
            span_text = "\n".join(lines[header_idx:end_idx]).strip()
            if not span_text:
                continue

            score = 0
            if "comparative totals of currency and coins in circulation" in context:
                score += 8
            if "currency in circulation by denomination" in context:
                score += 5
            if "table uscc-2" in context:
                score += 3
            if "amounts outstanding and in circulation" in context:
                score += 2
            if _has_per_capita(lines, idx):
                score += 2
            score += max(0, 12 - (date_idx - idx))

            candidate = {
                "score": score,
                "header_idx": header_idx,
                "end_idx": end_idx,
                "span_text": span_text,
            }
            if best is None or candidate["score"] > best["score"]:
                best = candidate

        if best is None:
            return []

        span = {"text": best["span_text"]}
        if line_objs and isinstance(line_objs[0], dict):
            start_line = line_objs[best["header_idx"]]
            end_line = line_objs[max(best["end_idx"] - 1, best["header_idx"])]
            if start_line.get("page_no") is not None:
                span["page_no"] = start_line.get("page_no")
            if start_line.get("line_no") is not None:
                span["line_no"] = start_line.get("line_no")
            if end_line.get("page_no") is not None:
                span["end_page_no"] = end_line.get("page_no")
            if end_line.get("line_no") is not None:
                span["end_line_no"] = end_line.get("line_no")

        return [span]
    except Exception:
        return []

